mapper.select:
SELECT c.id, c.name, c.course_id, c.teacher_id, c.description, c.created_time, co.name as course_name, co.description as course_description, u.username as teacher_username, u.nickname as teacher_nickname, u.real_name as teacher_real_name, u.email as teacher_email FROM classes c LEFT JOIN courses co ON c.course_id = co.id AND co.deleted = 0 LEFT JOIN users u ON c.teacher_id = u.id AND u.deleted = 0 WHERE 1=1
AND c.course_id = #{courseId}
AND c.teacher_id = #{teacherId}
AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.created_time DESC
